function financeBlock(f){if(!f)return'';return `<div class="page-title page-title-tight"><h2>${i18n.t('financialOverview')}</h2></div><div class="finance-grid"><div class="finance-stat"><small>${i18n.t('totalBilled').toUpperCase()}</small><b>₹${f.total_billed.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('collected').toUpperCase()}</small><b>₹${f.total_collected.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('pending').toUpperCase()}</small><b>₹${f.total_pending.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('expenses').toUpperCase()}</small><b>₹${f.total_expenses.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('balance').toUpperCase()}</small><b>₹${f.balance.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('collectionRate').toUpperCase()}</small><b>${f.collection_rate}%</b><div class="progress-track"><div class="progress-fill pct-w-${pctClass(Math.min(f.collection_rate,100))}"></div></div></div></div>`}
async function vendorperformance(c){const d=await api('/admin/vendor-performance');c.innerHTML=`<div class="page-title"><h2>${i18n.t('vendorPerformance')}</h2><p>${i18n.t('vendorPerfSubtitle')}</p></div>${d.vendor_performance.length?d.vendor_performance.map(v=>`<div class="perf-card"><div class="perf-head"><b>${esc(v.vendor.name)}</b><span class="perf-score">${v.score}/100</span></div><div class="perf-metrics"><div><small>Total jobs</small><b>${v.total_jobs}</b></div><div><small>${i18n.t('completed')}</small><b>${v.completed_jobs}</b></div><div><small>${i18n.t('cancelledLabel')}</small><b>${v.cancelled_jobs}</b></div><div><small>${i18n.t('completionRate')}</small><b>${v.completion_rate}%</b></div><div><small>${i18n.t('activeJobs')}</small><b>${v.active_jobs}</b></div><div><small>${i18n.t('avgRatingLabel')}</small><b>${v.vendor.average_rating!=null?'★ '+v.vendor.average_rating:'—'}</b></div></div>${v.average_completion_hours!=null?`<p class="muted muted perf-time">${i18n.t('avgCompletionTime')}: ${v.average_completion_hours}h</p>`:''}</div>`).join(''):`<div class="panel empty">${i18n.t('noVendorsYet')}</div>`}`}
function statusLabel(s){if(!s)return'';const key='status'+String(s).split('_').map(w=>w?w[0].toUpperCase()+w.slice(1):'').join('');return i18n.t(key)!==key?i18n.t(key):s.replace('_',' ')}
function orderCard(w){return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.vendor_name)} · ${i18n.t('dueLabel')} ${esc(w.due_date||'—')}</p></div><div class="u-text-right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount u-mt-6">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div></div>`}

function residentOrderCard(w){
  state.quoteCache=state.quoteCache||{};
  if(Array.isArray(w.quotes)) state.quoteCache[w.id]=w.quotes;
  const assigned=w.vendor_id?`<div class="notice notice notice-soft"><span class="tag">${w.status==='completed'?i18n.t('completedByLabel'):i18n.t('pickedUpBy')}</span><h3 class="u-title-14">${esc(w.vendor_name)}${w.vendor_service?' · '+esc(w.vendor_service):''}</h3><p>${w.vendor_contact?'<i data-lucide="phone"></i> '+esc(w.vendor_contact):i18n.t('noContactOnFile')}${w.completed_at?' · '+i18n.t('completedAtLabel')+' '+new Date(w.completed_at).toLocaleString('en-IN'):w.accepted_at?' · '+i18n.t('acceptedAtLabel')+' '+new Date(w.accepted_at).toLocaleString('en-IN'):''}</p></div>`:'';const ratingBlock=w.status==='completed'&&w.vendor_id?(w.rating?`<div class="notice notice notice-warm"><span class="tag">${i18n.t('yourRatingLabel')}</span><h3 class="u-rating-stars">${'★'.repeat(w.rating.stars)}${'☆'.repeat(5-w.rating.stars)}</h3>${w.rating.remarks?`<p>${esc(w.rating.remarks)}</p>`:''}</div>`:`<div class="btn-row"><button class="secondary" data-nl-action="rateVendorModal" data-nl-args="${w.id}">${i18n.t('rateVendorBtn')}</button></div>`):'';const quoteCount=Number(w.quotes_count||((Array.isArray(w.quotes)&&w.quotes.length)||0));const quotesBtn=w.status==='open'?`<div class="btn-row"><button class="secondary" data-nl-action="quotesModal" data-nl-args="${w.id}"><i data-lucide="messages-square"></i> ${i18n.t('viewQuotesBtn')}${quoteCount?` (${quoteCount})`:''}</button></div>`:'';return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} ${w.due_date?'· '+i18n.t('neededBy')+' '+esc(w.due_date):''}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div class="u-text-right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount u-mt-6">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${assigned}${ratingBlock}${quotesBtn}${w.status==='open'?`<div class="btn-row"><button class="cancel" data-nl-action="cancelWorkOrder" data-nl-args="${w.id}">${i18n.t('cancelRequest')}</button></div>`:''}${w.vendor_id&&w.amount&&['accepted','in_progress','completed'].includes(w.status)?(w.payment_status==='paid'?`<div class="btn-row"><span class="badge paid">${i18n.t('vendorPaymentPaid')}</span></div>`:`<div class="btn-row"><button class="pay" data-nl-action="payVendor" data-nl-args="${w.id}">${i18n.t('payVendorBtn')} ₹${Number(w.amount).toLocaleString('en-IN')} →</button></div>`):''}</div>`}

function vendorOpenCard(w){const mq=w.my_quote;const quoteBlock=mq?`<div class="notice notice notice-lavender"><span class="tag">${i18n.t('yourQuoteLabel')}</span><h3 class="u-title-15">₹${Number(mq.amount).toLocaleString('en-IN')}</h3>${mq.note?`<p>${esc(mq.note)}</p>`:''}</div>`:'';const quoteBtn=mq?`<button class="secondary" data-nl-action="quoteModal" data-nl-args="${w.id}">${i18n.t('updateQuote')}</button><button class="cancel" data-nl-action="withdrawQuote" data-nl-args="${w.id},${mq.id}">${i18n.t('withdrawQuote')}</button>`:`<button class="secondary" data-nl-action="quoteModal" data-nl-args="${w.id}">${i18n.t('submitQuote')}</button>`;return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.apartment||i18n.t('apartmentNA'))} ${w.due_date?'· '+i18n.t('neededBy')+' '+esc(w.due_date):''}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div class="u-text-right">${w.amount?`<div class="amount">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${quoteBlock}<div class="btn-row"><button class="accept" data-nl-action="acceptWorkOrder" data-nl-args="${w.id}">${i18n.t('acceptJob')} →</button>${quoteBtn}</div></div>`}

