function adminOrderCard(w){const ratingLine=w.rating?`<p class="muted u-note-11">${i18n.t('ratingLabel')}: ${'★'.repeat(w.rating.stars)}${'☆'.repeat(5-w.rating.stars)}</p>`:'';const quotesBtn=w.status==='open'?`<div class="btn-row"><button class="secondary" data-nl-action="quotesModal" data-nl-args="${w.id}">${i18n.t('viewQuotesBtn')}${w.quotes_count?` (${w.quotes_count})`:''}</button></div>`:'';return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.resident_name||i18n.t('postedByAdmin'))}${w.apartment?' ('+esc(w.apartment)+')':''} → ${esc(w.vendor_name)}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div class="u-text-right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount u-mt-6">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${ratingLine}${quotesBtn}</div>`}

