async function rejectQuote(wid,qid){return withActionLock(`quote-reject:${qid}`,async()=>{try{await api(`/work-orders/${wid}/quotes/${qid}/reject`,{method:'PATCH'});toast(i18n.t('quoteDeclined'));const m=$('#modal');if(m)m.remove();quotesModal(wid)}catch(e){toast(userErrorMessage(e))}})}

