function rateVendorModal(wid){let selected=0;function starsHtml(){return [1,2,3,4,5].map(n=>`<span class="star-pick ${n<=selected?'is-selected':''}" data-n="${n}">★</span>`).join('')}function renderStars(){const row=$('#starRow');row.innerHTML=starsHtml();row.querySelectorAll('.star-pick').forEach(s=>s.onclick=()=>{selected=Number(s.dataset.n);renderStars()})}document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" data-nl-action="__closeModal">×</button><h3>${i18n.t('rateVendorModalTitle')}</h3><div id="starRow" class="star-row"></div><form id="rf2"><div class="field"><label>${i18n.t('remarksOptional')}</label><textarea id="rremarks" rows="3"></textarea></div><button class="primary">${i18n.t('submitRatingBtn')}</button></form></div></div>`);renderStars();let submitting=false;$('#rf2').onsubmit=async e=>{e.preventDefault();if(submitting)return;if(!selected){toast(i18n.t('pickStarRating'));return}submitting=true;const button=e.currentTarget.querySelector('button[type=submit]');if(button)button.disabled=true;try{await api(`/work-orders/${wid}/rating`,{method:'POST',body:JSON.stringify({stars:selected,remarks:$('#rremarks').value})});$('#modal').remove();toast(i18n.t('ratingSubmitted'));loadPage()}catch(x){submitting=false;if(button)button.disabled=false;toast(userErrorMessage(x))}}}

function quoteHistoryCard(q){return `<div class="list-card"><div class="list-row"><div><h4>${esc(q.work_order_title||'—')}</h4><p>${esc(q.work_order_category||'')}${q.work_order_apartment?' · '+esc(q.work_order_apartment):''}</p>${q.note?`<p>${esc(q.note)}</p>`:''}</div><div class="u-text-right"><div class="amount">₹${Number(q.amount).toLocaleString('en-IN')}</div><span class="badge ${esc(q.status)}">${statusLabel(q.status)}</span></div></div>${q.status==='pending'?`<div class="btn-row"><button class="cancel" data-nl-action="withdrawQuote" data-nl-args="${q.work_order_id},${q.id}">${i18n.t('withdrawQuote')}</button></div>`:''}</div>`}

async function downloadReceipt(id, clickEvent){
  const button=clickEvent&&clickEvent.currentTarget?clickEvent.currentTarget:null;
  const original=button?button.textContent:'';
  try{
    if(button){button.disabled=true;button.textContent='Preparing PDF…'}
    const d=await api(`/payments/${id}/receipt-link`,{method:'POST'});
    if(!d.url) throw new Error(i18n.t('receiptDownloadFailed'));

    // Let the browser perform a normal navigation to an endpoint that returns
    // Content-Disposition: attachment. No blob, object URL, or popup is used.
    const link=document.createElement('a');
    link.href=new URL(d.url,window.location.origin).href;
    link.target='_blank';
    link.rel='noopener';
    link.style.display='none';
    document.body.appendChild(link);
    link.click();
    setTimeout(()=>link.remove(),1000);
  }catch(e){
    toast(e.message||i18n.t('receiptDownloadFailed'));
  }finally{
    if(button){button.disabled=false;button.textContent=original||i18n.t('downloadReceipt')}
  }
}

async function workOrderModal(isAdmin){let vendorOptions='',residentOptions='';if(isAdmin){const [vd,ud]=await Promise.all([api('/admin/vendors'),api('/admin/users')]);vendorOptions=(vd.vendors||[]).map(v=>`<option value="${v.id}">${esc(v.name)} (${esc(v.service)})</option>`).join('');residentOptions=(ud.users||[]).filter(u=>u.role==='resident').map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.apartment||'no unit')}</option>`).join('')}const cats=[['Plumbing','catPlumbing'],['Electrical','catElectrical'],['Carpentry','catCarpentry'],['Cleaning','catCleaning'],['Painting','catPainting']];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" data-nl-action="__closeModal">×</button><h3>${isAdmin?i18n.t('postWorkOrderModalTitle'):i18n.t('newMaintenanceRequestModalTitle')}</h3><form id="wf"><div class="field"><label>${i18n.t('categoryLabel')}</label><select id="wcat">${cats.map(([v,k])=>`<option value="${v}">${i18n.t(k)}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('titleLabel')}</label><input id="wtitle" required placeholder="e.g. Fix leaking kitchen tap"></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><textarea id="wdesc" rows="3" placeholder="${i18n.t('vendorDetailsPlaceholder')}"></textarea></div><div class="grid2"><div class="field"><label>${i18n.t('budgetOptional')}</label><input id="wamt" type="number" min="0" step="1" placeholder="₹"></div><div class="field"><label>${i18n.t('neededBy')}</label><input id="wdue" placeholder="e.g. 10 Sep 2026"></div></div>${isAdmin?`<div class="field"><label>${i18n.t('residentOptional')}</label><select id="wres"><option value="">${i18n.t('noneOption')}</option>${residentOptions}</select></div><div class="field"><label>${i18n.t('assignVendorOptional')}</label><select id="wven"><option value="">${i18n.t('leaveOpenOption')}</option>${vendorOptions}</select></div>`:''}<button class="primary">${isAdmin?i18n.t('postWorkOrderSubmit'):i18n.t('submitRequest')}</button></form></div></div>`);let submitting=false;$('#wf').onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;const form=e.currentTarget;const button=form.querySelector('button[type=submit],button');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent=isAdmin?'Posting...':'Submitting...'}try{const body={category:$('#wcat').value,title:$('#wtitle').value,description:$('#wdesc').value,amount:$('#wamt').value||0,due_date:$('#wdue').value};if(isAdmin){const rv=$('#wres').value,vv=$('#wven').value;if(rv)body.resident_id=Number(rv);if(vv)body.vendor_id=Number(vv)}const result=await api('/work-orders',{method:'POST',body:JSON.stringify(body)});$('#modal').remove();toast(result.duplicate?(isAdmin?'Work order already submitted':'Request already submitted'):(isAdmin?i18n.t('workOrderPosted'):i18n.t('requestSubmitted')));loadPage()}catch(x){submitting=false;if(button){button.disabled=false;button.textContent=button.dataset.originalText||button.textContent}toast(userErrorMessage(x))}}}
async function payments(c){
    if(state.role==='admin'){
        const [p,b]=await Promise.all([api(listApiPath('payments','/admin/payments')),api('/admin/maintenance-bills')]);
        c.innerHTML=`<div class="page-title"><h2>${i18n.t('payments')}</h2><p>${i18n.t('adminPaymentsSubtitle')}</p></div>
        <div class="panel u-mb-18"><div class="panel-head"><div><h3>${i18n.t('maintenanceBilling')}</h3><p class="muted">${i18n.t('maintenanceBillingSubtitle')}</p></div><div class="btn-row"><button class="secondary" data-nl-action="exportList" data-nl-args="'maintenance-bills','csv','payments'"><i data-lucide="file-text"></i> CSV bills</button><button class="secondary" data-nl-action="exportList" data-nl-args="'maintenance-bills','xlsx','payments'"><i data-lucide="file-spreadsheet"></i> Excel bills</button><button class="primary u-auto" data-nl-action="maintenanceBillModal" data-nl-args="">${i18n.t('assignMaintenance')}</button></div>
        ${b.bills.length?`<table class="table"><thead><tr><th>${i18n.t('tableUser')}</th><th>${i18n.t('tableApartment')}</th><th>${i18n.t('billingMonth')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('dueDate')}</th><th>${i18n.t('tableStatus')}</th></tr></thead><tbody>${b.bills.map(x=>`<tr><td>${esc(x.resident_name||x.user_id)}</td><td>${esc(x.apartment||'—')}</td><td>${esc(x.month)}</td><td>₹${Number(x.amount).toLocaleString('en-IN')}</td><td>${esc(x.due_date)}</td><td><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${i18n.t('noMaintenanceBills')}</div>`}</div>
        <div class="panel"><div class="panel-head"><h3>${i18n.t('paymentHistory')}</h3></div>
        ${p.payments.length?`<table class="table"><thead><tr><th>${i18n.t('tableDate')}</th><th>${i18n.t('tableUser')}</th><th>${i18n.t('tableDescription')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('tableStatus')}</th><th>${i18n.t('tableReceipt')}</th></tr></thead>
        <tbody>${p.payments.map(x=>`<tr><td>${new Date(x.created_at).toLocaleDateString('en-IN')}</td><td>${esc(x.user_name||x.user_id)}</td><td>${esc(x.description)}</td><td>₹${Number(x.amount).toLocaleString('en-IN')}</td><td><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></td><td>${x.status==='paid'?`<button class="secondary" data-nl-action="downloadReceipt" data-nl-args="${x.id}, event">${i18n.t('downloadReceipt')}</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:`<div class="empty">${i18n.t('noPaymentsYet')}</div>`}</div>`;
        return;
    }

    const [d,p]=await Promise.all([api('/bills'),api(listApiPath('payments','/payments'))]);
    c.innerHTML=`<div class="page-title"><h2>${i18n.t('payments')}</h2><p>${i18n.t('residentPaymentsSubtitle')}</p></div>
    ${d.bills.length?d.bills.map(b=>`<div class="list-card"><div class="list-row"><div><h4>${esc(b.description)}</h4><p>${esc(b.month)} · ${i18n.t('dueLabel')} ${esc(b.due_date)}</p></div>
    <div class="u-text-right"><div class="amount">₹${Number(b.amount).toLocaleString('en-IN')}</div>${b.status==='paid'?`<span class="badge paid">${i18n.t('statusPaid')}</span>`:`<button class="pay" data-nl-action="payBill" data-nl-args="${b.id}">${i18n.t('payNow')} →</button>`}</div></div></div>`).join(''):`<div class="panel empty">${i18n.t('noMaintenanceBills')}</div>`}
    <div class="panel u-mt-18"><div class="panel-head"><h3>${i18n.t('paymentHistory')}</h3></div>
    ${p.payments.length?`<table class="table"><thead><tr><th>${i18n.t('tableDate')}</th><th>${i18n.t('tableDescription')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('tableStatus')}</th><th>${i18n.t('tableReceipt')}</th></tr></thead>
    <tbody>${p.payments.map(x=>`<tr><td>${new Date(x.created_at).toLocaleDateString('en-IN')}</td><td>${esc(x.description)}</td><td>₹${Number(x.amount).toLocaleString('en-IN')}</td><td><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></td><td>${x.status==='paid'?`<button class="secondary" data-nl-action="downloadReceipt" data-nl-args="${x.id}, event">${i18n.t('downloadReceipt')}</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:`<div class="empty">${i18n.t('noPaymentsYet')}</div>`}</div>`;
}

function maintenanceBillModal(){api('/admin/users').then(d=>{const residents=d.users.filter(u=>u.role==='resident');document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" data-nl-action="__closeModal">×</button><h3>${i18n.t('assignMaintenance')}</h3><div id="billFormError"></div><form id="mbf"><div class="field"><label>${i18n.t('tableUser')}</label><select id="mbres" required>${residents.map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.apartment||'no unit')}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>${i18n.t('billingMonth')}</label><input id="mbmonth" required placeholder="September 2026"></div><div class="field"><label>${i18n.t('dueDate')}</label><input id="mbdue" required placeholder="05 October 2026"></div></div><div class="field"><label>${i18n.t('tableAmount')}</label><input id="mbamount" type="number" min="1" step="0.01" required placeholder="2500"></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><input id="mbdesc" value="Monthly Maintenance" maxlength="255"></div><button class="primary">${i18n.t('assignMaintenance')}</button></form></div></div>`);let submitting=false;$('#mbf').onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;const form=e.currentTarget,button=form.querySelector('button[type=submit]');if(button)button.disabled=true;const error=$('#billFormError');error.innerHTML='';try{await api('/admin/maintenance-bills',{method:'POST',body:JSON.stringify({resident_id:Number($('#mbres').value),month:$('#mbmonth').value,due_date:$('#mbdue').value,amount:Number($('#mbamount').value),description:$('#mbdesc').value})});$('#modal').remove();toast(i18n.t('maintenanceAssigned'));loadPage()}catch(x){submitting=false;if(button)button.disabled=false;error.innerHTML=`<div class="error">${esc(x.message)}</div>`}}}).catch(e=>toast(userErrorMessage(e)))}
async function payVendor(id){return withActionLock(`pay-work:${id}`,async()=>{try{const o=await api('/payments/work-order/create-order',{method:'POST',body:JSON.stringify({work_order_id:id})});if(typeof Razorpay==='undefined')throw new Error(i18n.t('razorpayLoadError'));const r=new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,name:o.name,description:o.description,order_id:o.order_id,prefill:{name:state.user.name,email:state.user.email},handler:async resp=>{try{await api('/payments/verify',{method:'POST',body:JSON.stringify(resp)});toast(i18n.t('vendorPaymentVerified'));loadPage()}catch(e){toast(userErrorMessage(e))}}});r.open()}catch(e){toast(userErrorMessage(e))}})}
async function payBill(id){return withActionLock(`pay-bill:${id}`,async()=>{try{const o=await api('/payments/create-order',{method:'POST',body:JSON.stringify({bill_id:id})});if(typeof Razorpay==='undefined')throw new Error(i18n.t('razorpayLoadError'));const r=new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,name:o.name,description:o.description,order_id:o.order_id,prefill:{name:state.user.name,email:state.user.email},theme:{color:'#9b83c7'},handler:async resp=>{try{await api('/payments/verify',{method:'POST',body:JSON.stringify(resp)});toast(i18n.t('paymentVerified'));loadPage()}catch(e){toast(userErrorMessage(e))}}});r.open()}catch(e){toast(userErrorMessage(e))}})}
async function receipts(c){const d=await api(listApiPath('receipts','/payments','paid'));c.innerHTML=`<div class="page-title"><h2>${i18n.t('receipts')}</h2><p>${i18n.t('receiptsSubtitle')}</p></div>${d.payments.filter(p=>p.status==='paid').map(p=>`<div class="list-card"><div class="list-row"><div><h4>${i18n.t('maintenanceReceipt')} #${p.id}</h4><p>${new Date(p.created_at).toLocaleDateString('en-IN')} · ${esc(p.razorpay_payment_id||i18n.t('verifiedLabel'))}</p></div><div class="u-text-right"><div class="amount">₹${p.amount.toLocaleString('en-IN')}</div><button class="secondary u-mt-8" data-nl-action="downloadReceipt" data-nl-args="${p.id}, event">${i18n.t('downloadReceipt')}</button></div></div></div>`).join('')||`<div class="panel empty">${i18n.t('noReceiptsYet')}</div>`}`}
function complaintTimeline(status){const steps=[['open','timelineSubmitted'],['in_progress','timelineInProgress'],['resolved','timelineResolved'],['closed','timelineClosed']];const idx=steps.findIndex(s=>s[0]===status);return `<div class="timeline">${steps.map((s,i)=>`<div class="timeline-step ${i<idx?'done':''} ${i===idx?'current':''}"><div class="timeline-dot">${i<idx?'✓':i===idx?'●':'<i data-lucide="circle-user-round"></i>'}</div><div class="timeline-label">${i18n.t(s[1])}</div></div>`).join('')}</div>`}
async function complaints(c){const d=await api(listApiPath('complaints','/complaints'));c.innerHTML=`<div class="page-title"><h2>${i18n.t('complaints')}</h2><p>${i18n.t('complaintsSubtitle')}</p></div><div class="page-actions">${state.role==='resident'?`<button class="primary" data-nl-action="complaintModal" data-nl-args=""><i data-lucide="message-circle-plus"></i>${i18n.t('newComplaint')}</button>`:''}</div>${d.complaints.map(x=>`<article class="list-card complaint-card"><div class="list-row"><div><span class="tag">${esc(x.category)}</span><h4>${esc(x.subject)}</h4><p>${esc(x.description)}</p><small class="muted">${x.resident_name?esc(x.resident_name)+' · ':''}${new Date(x.created_at).toLocaleDateString('en-IN')}</small></div><div class="complaint-actions"><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span>${state.role==='admin'?`<select class="status-select" data-complaint-id="${x.id}"><option value="open" ${x.status==='open'?'selected':''}>Open</option><option value="in_progress" ${x.status==='in_progress'?'selected':''}>In Progress</option><option value="resolved" ${x.status==='resolved'?'selected':''}>Resolved</option><option value="closed" ${x.status==='closed'?'selected':''}>Closed</select>`:''}</div></div>${state.role==='resident'?complaintTimeline(x.status):''}</article>`).join('')||`<div class="empty-state"><i data-lucide="circle-check"></i><h4>${i18n.t('noComplaintsYet')}</h4><p>${i18n.t('raiseComplaint')}</p></div>`}`;
  if(state.role==='admin'){ c.querySelectorAll('.status-select[data-complaint-id]').forEach(select=>{select.addEventListener('change',()=>updateComplaintStatus(Number(select.dataset.complaintId),select.value));}); }
  renderIcons();
}
async function updateComplaintStatus(id,status){try{await api('/complaints/'+id,{method:'PATCH',body:JSON.stringify({status})});toast('Complaint status updated');loadPage()}catch(e){toast(userErrorMessage(e))}}

function complaintModal(){const cats=[['Plumbing','catPlumbing'],['Electrical','catElectrical'],['Security','catSecurity'],['Cleaning','catCleaning'],['Other','catOther']];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" data-nl-action="__closeModal">×</button><h3>${i18n.t('raiseComplaint')}</h3><form id="cf"><div class="field"><label>${i18n.t('categoryLabel')}</label><select id="cc">${cats.map(([v,k])=>`<option value="${v}">${i18n.t(k)}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('subjectLabel')}</label><input id="cs" required></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><textarea id="cd" rows="4" required></textarea></div><button class="primary">${i18n.t('submitComplaint')}</button></form></div></div>`);let submitting=false;$('#cf').onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;const form=e.currentTarget;const button=form.querySelector('button[type=submit],button');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Submitting...'}try{const result=await api('/complaints',{method:'POST',body:JSON.stringify({category:$('#cc').value,subject:$('#cs').value,description:$('#cd').value})});$('#modal').remove();toast(result.duplicate?'Complaint already submitted':i18n.t('complaintSubmitted'));loadPage()}catch(x){submitting=false;if(button){button.disabled=false;button.textContent=button.dataset.originalText||button.textContent}toast(userErrorMessage(x))}}}
async function notices(c){const d=await api(listApiPath('notices','/notices'));const isAdmin=state.role==='admin';c.innerHTML=`<div class="page-title"><h2>${i18n.t('notices')}</h2><p>${i18n.t('noticesSubtitle')}</p></div>${isAdmin?`<button class="primary u-auto u-mb-15" data-nl-action="noticeModal" data-nl-args="">${i18n.t('postNotice')}</button>`:''}${d.notices.length?d.notices.map(n=>`<div class="notice"><span class="tag">${esc(n.tag)} · ${new Date(n.created_at).toLocaleDateString('en-IN',{day:'2-digit',month:'short'}).toUpperCase()}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${isAdmin?`<div class="btn-row"><button class="cancel" data-nl-action="deleteNotice" data-nl-args="${n.id}">${i18n.t('deleteBtn')}</button></div>`:''}</div>`).join(''):`<div class="panel empty">${i18n.t('noNoticesYet')}</div>`}`}
function noticeModal(){const tags=[['COMMUNITY','tagCommunity'],['IMPORTANT','tagImportant'],['MAINTENANCE','tagMaintenance'],['EVENT','tagEvent']];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" data-nl-action="__closeModal">×</button><h3>${i18n.t('postNoticeModalTitle')}</h3><form id="nf"><div class="field"><label>${i18n.t('tagLabel')}</label><select id="ntag">${tags.map(([v,k])=>`<option value="${v}">${i18n.t(k)}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('titleLabel')}</label><input id="ntitle" required placeholder="e.g. Water tank cleaning"></div><div class="field"><label>${i18n.t('messageLabel')}</label><textarea id="nbody" rows="4" required></textarea></div><button class="primary">${i18n.t('postNoticeBtn')}</button></form></div></div>`);let submitting=false;$('#nf').onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;const button=e.currentTarget.querySelector('button[type=submit]');if(button)button.disabled=true;try{const result=await api('/notices',{method:'POST',body:JSON.stringify({tag:$('#ntag').value,title:$('#ntitle').value,body:$('#nbody').value})});$('#modal').remove();toast(result?.duplicate?'Notice already posted':i18n.t('noticePosted'));loadPage()}catch(x){submitting=false;if(button)button.disabled=false;toast(userErrorMessage(x))}}}
async function deleteNotice(id){if(!confirm(i18n.t('confirmDeleteNotice')))return;try{await api('/notices/'+id,{method:'DELETE'});toast(i18n.t('noticeDeleted'));loadPage()}catch(e){toast(userErrorMessage(e))}}
function profile(c){c.innerHTML=`<div class="page-title"><h2>${i18n.t('myProfile')}</h2><p>${i18n.t('profileSubtitle')}</p></div><div class="profile-box"><div class="big-avatar">${esc(state.user.name[0].toUpperCase())}</div><div><h3 class="u-margin-0">${esc(state.user.name)}</h3><p class="muted">${esc(state.user.email)} · ${esc(i18n.t(state.user.role))}</p></div></div><div class="form-card"><form id="pf"><div class="grid2"><div class="field"><label>${i18n.t('name')}</label><input id="pn" value="${esc(state.user.name)}" required></div><div class="field"><label>${i18n.t('phone')}</label><input id="pp" value="${esc(state.user.phone||'')}"></div></div><div class="field"><label>${i18n.t('apartment')}</label>${apartmentPickerHtml('pa')}</div><button class="primary">${i18n.t('save')}</button></form></div>`;initApartmentPicker('pa', state.user.apartment||'');let submitting=false;$('#pf').onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;const button=e.currentTarget.querySelector('button[type=submit]');if(button)button.disabled=true;try{const d=await api('/auth/profile',{method:'PUT',body:JSON.stringify({name:$('#pn').value,phone:$('#pp').value,apartment:$('#pa').value})});state.user=d.user;toast(i18n.t('profileUpdated'));renderShell()}catch(x){submitting=false;if(button)button.disabled=false;toast(userErrorMessage(x))}}}
async function residents(c){const d=await api(listApiPath('residents','/admin/users'));const users=d.users;c.innerHTML=`<div class="page-title"><h2>${i18n.t('residents')}</h2><p>${i18n.t('residentsSubtitle')}</p></div><div class="page-actions"><button class="primary" data-nl-action="residentModal" data-nl-args=""><i data-lucide="user-round-plus"></i>Add resident</button></div><div class="panel resident-directory"><div class="directory-grid">${users.map(u=>`<button class="resident-card" data-nl-action="residentDetail" data-nl-args="${u.id}"><span class="avatar large">${esc((u.name||'U')[0].toUpperCase())}</span><span><b>${esc(u.name)}</b><small>${esc(u.apartment||'No unit')}</small><small>${esc(u.email)}</small></span><i data-lucide="arrow-up-right"></i></button>`).join('')||`<div class="empty-state"><i data-lucide="users-round"></i><h4>No residents yet</h4><p>Add your first resident to begin the directory.</p></div>`}</div></div>`;renderIcons()}
async function residentDetail(id){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="residentDetailModal"><div class="modal modal-wide"><button type="button" class="close" data-nl-action="__closeResidentDetail"><i data-lucide="x"></i></button><div id="residentDetailBody" class="page-loading"><span class="loading-spinner"></span><span>${i18n.t('loading')}</span></div></div></div>`);renderIcons();try{const d=await api('/admin/residents/'+id),r=d.resident;const paid=d.payments.filter(x=>x.status==='paid').reduce((a,x)=>a+Number(x.amount||0),0),due=d.bills.filter(x=>x.status!=='paid').reduce((a,x)=>a+Number(x.amount||0),0);
  state.listFilters=state.listFilters||{};
  state.listFilters.payments=state.listFilters.payments||{page:1,q:'',status:''};
  const paymentRows=d.payments.slice(0,8).map(x=>`<div class="list-row compact"><div><b>${esc(x.description||'Payment')}</b><p>${new Date(x.created_at).toLocaleDateString('en-IN')} · <span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></p></div><div class="detail-payment-actions"><strong>₹${Number(x.amount||0).toLocaleString('en-IN')}</strong>${x.status==='paid'?`<button type="button" class="secondary" data-nl-action="downloadReceipt" data-nl-args="${x.id}, event"><i data-lucide="receipt-text"></i>${i18n.t('downloadReceipt')}</button>`:''}</div></div>`).join('');
  $('#residentDetailBody').innerHTML=`<div class="detail-head"><div class="avatar large">${esc((r.name||'U')[0].toUpperCase())}</div><div><span class="eyebrow">Resident profile</span><h2>${esc(r.name)}</h2><p>${esc(r.apartment||'No unit')} · ${esc(r.email)}</p></div></div><div class="detail-actions"><button type="button" class="secondary" data-nl-action="viewResidentPayments" data-nl-args="'${encodeURIComponent(r.name)}'"><i data-lucide="indian-rupee"></i> View payments</button></div><div class="cards detail-stats"><div class="stat"><small>Outstanding</small><b>₹${due.toLocaleString('en-IN')}</b></div><div class="stat"><small>Total paid</small><b>₹${paid.toLocaleString('en-IN')}</b></div><div class="stat"><small>Complaints</small><b>${d.complaints.length}</b></div><div class="stat"><small>Maintenance</small><b>${d.work_orders.length}</b></div></div><div class="detail-columns"><div class="panel"><div class="panel-head"><div><h3>Payment history</h3><p class="muted">Paid transactions include a working receipt action.</p></div></div>${paymentRows||`<div class="empty-state"><i data-lucide="receipt"></i><h4>No payments yet</h4></div>`}</div><div class="panel"><h3>Open items</h3>${[...d.complaints.filter(x=>x.status!=='closed').map(x=>`<div class="list-row compact"><div><b>${esc(x.subject)}</b><p>Complaint</p></div><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></div>`),...d.work_orders.filter(x=>!['completed','cancelled'].includes(x.status)).map(x=>`<div class="list-row compact"><div><b>${esc(x.title)}</b><p>Maintenance</p></div><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></div>`)].join('')||`<div class="empty-state"><i data-lucide="badge-check"></i><h4>Nothing needs attention</h4></div>`}</div></div>`;renderIcons()}catch(e){$('#residentDetailBody').innerHTML=`<div class="error">${esc(e.message)}</div>`}}

function residentModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" data-nl-action="__closeModal">×</button><h3>Add resident</h3><div id="residentFormError"></div><form id="rf" novalidate><div class="field"><label>Name</label><input id="rn" autocomplete="name"></div><div class="field"><label>Email</label><input id="re" type="email" autocomplete="email"></div><div class="field"><label>Phone</label><input id="rp" inputmode="numeric" placeholder="9876543210" autocomplete="tel"></div><div class="field"><label>Apartment / Flat</label>${apartmentPickerHtml('ra')}</div><button id="residentSubmit" type="submit" class="primary">Create resident</button></form></div></div>`);initApartmentPicker('ra');$('#rf').onsubmit=async e=>{e.preventDefault();const name=$('#rn').value.trim(),email=$('#re').value.trim(),phone=$('#rp').value.trim(),apartment=$('#ra').value.trim(),error=$('#residentFormError'),button=$('#residentSubmit');error.innerHTML='';if(!name||!email||!phone||!apartment){error.innerHTML='<div class="error">Please fill in Name, Email, Phone and Apartment / Flat.</div>';return}if(!validEmail(email)){error.innerHTML='<div class="error">Enter a valid email address.</div>';return}if(!validPhone(phone)){error.innerHTML='<div class="error">Enter a valid 10-digit Indian phone number.</div>';return}button.disabled=true;button.textContent='Creating...';try{const d=await api('/admin/residents',{method:'POST',body:JSON.stringify({name,email,phone,apartment})});$('#modal').remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="tempPasswordModal"><div class="modal"><button type="button" class="close" data-nl-action="__closeTempPassword">×</button><h3>Resident created</h3><p>Give this temporary password to the resident. It is shown only once.</p><div class="panel"><b>${esc(d.temporary_password)}</b></div><button type="button" class="primary" data-nl-action="__closeTempPassword">Done</button></div></div>`)}catch(x){error.innerHTML=`<div class="error">${esc(x.message)}</div>`;toast(userErrorMessage(x));button.disabled=false;button.textContent='Create resident'}}}
async function vendors(c){const d=await api(listApiPath('vendors','/admin/vendors'));c.innerHTML=`<div class="page-title"><h2>${i18n.t('vendors')}</h2><p>${i18n.t('vendorsSubtitle')}</p></div><button class="primary u-auto u-mb-15" data-nl-action="vendorModal" data-nl-args="">${i18n.t('addVendor')}</button><div class="panel"><table class="table"><thead><tr><th>${i18n.t('tableName')}</th><th>Job title</th><th>${i18n.t('tableContact')}</th><th>${i18n.t('tableStatus')}</th><th>${i18n.t('tableRating')}</th></tr></thead><tbody>${d.vendors.map(v=>`<tr><td>${esc(v.name)}</td><td>${esc(v.service)}</td><td>${esc(v.contact)}</td><td><span class="badge ${v.status}">${statusLabel(v.status)}</span></td><td>${v.average_rating!=null?'★ '+v.average_rating+' ('+v.rating_count+')':i18n.t('noRatingsYet')}</td></tr>`).join('')||`<tr><td colspan="5">No vendors yet</td></tr>`}</tbody></table></div>`}
function vendorModal(){const jobs=['Plumber','Electrician','Carpenter','Painter','Cleaner'];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" data-nl-action="__closeModal">×</button><h3>${i18n.t('addVendorModalTitle')}</h3><div id="vendorFormError"></div><form id="vf" novalidate><div class="field"><label>${i18n.t('name')}</label><input id="vn" autocomplete="name"></div><div class="field"><label>Email</label><input id="ve" type="email" autocomplete="email"></div><div class="field"><label>Password</label><input id="vp" type="password" minlength="8" autocomplete="new-password"></div><div class="field"><label>Job title</label><select id="vs">${jobs.map(j=>`<option value="${j}">${j}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('contactLabel')}</label><input id="vc" inputmode="numeric" placeholder="9876543210" autocomplete="tel"></div><button id="vendorSubmit" type="submit" class="primary">${i18n.t('saveVendor')}</button></form></div></div>`);$('#vf').onsubmit=async e=>{e.preventDefault();const name=$('#vn').value.trim(),email=$('#ve').value.trim(),password=$('#vp').value,job_title=$('#vs').value,contact=$('#vc').value.trim(),error=$('#vendorFormError'),button=$('#vendorSubmit');error.innerHTML='';if(!name||!email||!password||!contact){error.innerHTML='<div class="error">Please fill in Name, Email, Password and Contact.</div>';return}if(!validEmail(email)){error.innerHTML='<div class="error">Enter a valid email address.</div>';return}if(password.length<8){error.innerHTML='<div class="error">Password must be at least 8 characters.</div>';return}if(!validPhone(contact)){error.innerHTML='<div class="error">Enter a valid 10-digit Indian phone number.</div>';return}button.disabled=true;button.textContent='Creating...';try{await api('/admin/vendors',{method:'POST',body:JSON.stringify({name,email,password,job_title,contact})});$('#modal').remove();toast('Vendor account created successfully');loadPage()}catch(x){error.innerHTML=`<div class="error">${esc(x.message)}</div>`;toast(userErrorMessage(x));button.disabled=false;button.textContent=i18n.t('saveVendor')}}}
async function expenses(c){const d=await api(listApiPath('expenses','/admin/expenses'));c.innerHTML=`<div class="page-title"><h2>${i18n.t('expenses')}</h2><p>${i18n.t('expensesSubtitle')}</p></div><button class="primary u-auto u-mb-15" data-nl-action="expenseModal" data-nl-args="">${i18n.t('addExpense')}</button><div class="panel"><table class="table"><thead><tr><th>${i18n.t('tableCategory')}</th><th>${i18n.t('tableDescription')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('tableDate')}</th></tr></thead><tbody>${d.expenses.map(e=>`<tr><td>${esc(e.category)}</td><td>${esc(e.description)}</td><td>₹${e.amount.toLocaleString('en-IN')}</td><td>${new Date(e.created_at).toLocaleDateString('en-IN')}</td></tr>`).join('')||`<tr><td colspan="4">${i18n.t('noExpensesRow')}</td></tr>`}</tbody></table></div>`}
function expenseModal(){
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" data-nl-action="__closeModal">×</button><h3>${i18n.t('addExpenseModalTitle')}</h3><form id="ef"><div class="field"><label>${i18n.t('categoryLabel')}</label><input id="ec" required></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><input id="ed" required></div><div class="field"><label>${i18n.t('amountLabel')}</label><input id="ea" type="number" min="0" step="0.01" required></div><button type="submit" class="primary">${i18n.t('saveExpense')}</button></form></div></div>`);
  let submitting=false;
  $('#ef').onsubmit=async e=>{
    e.preventDefault();
    if(submitting)return;
    submitting=true;
    const button=e.currentTarget.querySelector('button[type="submit"]');
    if(button)button.disabled=true;
    try{
      const result=await api('/admin/expenses',{method:'POST',body:JSON.stringify({category:$('#ec').value,description:$('#ed').value,amount:Number($('#ea').value)})});
      $('#modal').remove();
      toast(result?.duplicate?'Expense already added':i18n.t('expenseAdded'));
      loadPage();
    }catch(x){
      submitting=false;
      if(button)button.disabled=false;
      toast(userErrorMessage(x));
    }
  };
}

async function workorders(c){const d=await api(listApiPath('workorders','/work-orders'));const list=d.work_orders;if(state.role==='resident'){c.innerHTML=`<div class="page-title"><h2>${i18n.t('maintenanceRequests')}</h2><p>${i18n.t('maintenanceRequestsSubtitle')}</p></div><button class="primary u-auto u-mb-15" data-nl-action="workOrderModal" data-nl-args="">${i18n.t('newRequest')}</button>${list.length?list.map(residentOrderCard).join(''):`<div class="panel empty">${i18n.t('noRequestsYet')}</div>`}`}else if(state.role==='vendor'){const buckets=[['open',i18n.t('openRequests'),vendorOpenCard],['accepted',i18n.t('waitingToStart'),vendorMineCard],['in_progress',i18n.t('inProgress'),vendorMineCard],['completed',i18n.t('completed'),vendorMineCard],['cancelled',i18n.t('cancelledWithdrawn'),vendorMineCard]];c.innerHTML=`<div class="page-title"><h2>${i18n.t('jobBoardTitle')}</h2><p>${i18n.t('jobBoardSubtitle')}</p></div>${buckets.map(([status,label,cardFn])=>{const items=list.filter(w=>w.status===status);return `<div class="section-label">${label} · ${items.length}</div>${items.length?items.map(cardFn).join(''):`<div class="panel empty">${i18n.t('noData')}</div>`}`}).join('')}<div class="section-label">${i18n.t('myQuotationsTitle')}</div><div id="myQuotesBox"><div class="panel empty">${i18n.t('loading')}</div></div>`;try{const qd=await api('/vendors/me/quotes');const box=$('#myQuotesBox');if(box)box.innerHTML=qd.quotes.length?qd.quotes.map(quoteHistoryCard).join(''):`<div class="panel empty">${i18n.t('noQuotesSubmittedYet')}</div>`}catch(e){const box=$('#myQuotesBox');if(box)box.innerHTML=`<div class="error">${esc(e.message)}</div>`}}else{c.innerHTML=`<div class="page-title"><h2>${i18n.t('workorders')}</h2><p>${i18n.t('workOrdersSubtitle')}</p></div><button class="primary u-auto u-mb-15" data-nl-action="workOrderModal" data-nl-args="true">${i18n.t('postWorkOrder')}</button>${list.length?list.map(adminOrderCard).join(''):`<div class="panel empty">${i18n.t('noWorkOrdersYet')}</div>`}`}}
const PAGE_LOADERS={dashboard,payments,receipts,workorders,complaints,notices,profile,residents,vendors,vendorperformance,expenses,reports:businessIntelligence};
async function bootstrap(){try{const d=await api('/auth/me');state.token='cookie-session';state.user=d.user;state.role=d.user.role;window.NLRouter.syncFromUrl();render()}catch(e){window.NLState.clearSession();renderAuth('login')}}
window.addEventListener('popstate',()=>{if(!state.token)return;window.NLRouter.syncFromUrl();updateNavActive();loadPage()});
bootstrap();
// Keep data reasonably fresh without stacking refreshes when a page is already
// loading or when visibility/focus events fire close together.
function backgroundRefresh(){
  if(!state.token||document.visibilityState!=='visible')return;
  const now=Date.now();
  if(now-lastBackgroundRefreshAt<10000)return;
  if(activePageController)return;
  lastBackgroundRefreshAt=now;
  loadPage({silent:true});
}
setInterval(backgroundRefresh,30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')backgroundRefresh()});


